preConditionHook:
// TAKE THE WITH-TREND TRADE OFF AT THE THIRD PUSH. A channel usually corrects
// after a third push, so a long is closed once three pushes UP are complete
// and this bar turns down through the prior bar's low; a short is closed on
// three pushes down and a close above the prior bar's high.
//
// Same pattern as ThreePushReversalEntry's precondition but in the EXIT pane,
// where an Entry rule cannot sit -- and read on the CURRENT bar rather than
// the prior one, because an exit does not wait for a signal bar. That
// difference is deliberate and is what keeps the two from firing together.
//
// Pivot scan as in ThreePushPattern, inlined (rules here never reference each
// other; the register lists Occurrence 3+ as unmeasured, so the third push is
// found by hand). MEASURED (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60
// min): the pivot bar is AT OR ABOVE the swingStrength OLDER bars and STRICTLY
// ABOVE the swingStrength NEWER bars -- bars-ago indexing, so the newer bars
// are the smaller k and take el_gt / el_lt, the older el_ge / el_le;
// confirmation lag exactly swingStrength bars; candidate offsets
// swingStrength .. lookbackBars - 1, the neighbourhood reaching swingStrength
// bars past the window, so the deepest bar touched is
// lookbackBars - 1 + swingStrength. No early break, matching the twin.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)swingStrength;
pivWindow = (int)lookbackBars;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiPx1 = high[j];
        if (nHiPiv == 2) hiPx2 = high[j];
        if (nHiPiv == 3) hiPx3 = high[j];
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loPx1 = low[j];
        if (nLoPiv == 2) loPx2 = low[j];
        if (nLoPiv == 3) loPx3 = low[j];
    }
}
patUp = (nHiPiv == 3) && el_gt(hiPx1, hiPx2) && el_gt(hiPx2, hiPx3);
patDn = (nLoPiv == 3) && el_lt(loPx1, loPx2) && el_lt(loPx2, loPx3);
